ken)\n \n is ReportAction.OnResetDownloadState -> {\n update {\n copy(\n downloading = false,\n downloadSuccess = false,\n downloadError = false,\n downloadErrorMessage = \"\",\n downloadUrl = \"\"\n )\n }\n }\n \n is ReportAction.OnResetState -> {\n restartState()\n }\n }\n }\n\n private fun getReports(\n userId: Long,\n startDate: String,\n endDate: String,\n token: String\n ) {\n viewModelScope.launch {\n getReportsByUserIdByDate.execute(\n GetReportsByUserIdByDateUseCase.Params(\n userId,\n startDate,\n endDate,\n false,\n token\n )\n )\n .collectLatest { resource ->\n when (resource) {\n is Resource.Success -> {\n update {\n copy(\n isLoading = false,\n list = list.copy(\n reports = resource.data\n ),\n isSuccess = true,\n isEmpty = resource.data.isEmpty()\n )\n }\n }\n\n is Resource.Error -> {\n update {\n copy(\n isLoading = false,\n isError = true,\n errorMessage = resource.msg\n )\n }\n }\n\n Resource.Loading -> {\n update {\n copy(\n isLoading = true,\n isError = false,\n errorMessage = \"\"\n )\n }\n }\n }\n }\n }\n }\n \n private fun downloadReport(id: Long, token: String) {\n viewModelScope.launch {\n downloadReportUseCase.execute(DownloadReportUseCase.Params(id, token))\n .collectLatest { resource ->\n when (resource) {\n is Resource.Success -> {\n update {\n copy(\n downloading = false,\n downloadSuccess = true,\n downloadUrl = resource.data\n )\n }\n }\n is Resource.Error -> {\n update {\n copy(\n downloading = false,\n downloadError = true,\n downloadErrorMessage = resource.msg\n )\n }\n }\n Resource.Loading -> {\n update {\n copy(\n downloading = true,\n downloadError = false,\n downloadSuccess = false,\n downloadErrorMessage = \"\"\n )\n }\n }\n }\n }\n }\n }\n}", "instructions": "Create ReportViewModel to handle business logic", "target_file": "features/report/src/main/java/com/dailyapps/feature/report/ReportViewModel.kt"}"}}]},{"role":"tool","name":"edit_file","tool_call_id":"tooluse_6VlRGaT9SOy5zjg9NhishQ","content":"The apply model made the following changes to the file:

